"""Record layouts for loan. Generated by Séance from the COBOL record descriptions. Do not edit."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from seance.cobol_num import deedit, format_alpha, format_edited, format_numeric, parse_numeric

IN_WIDTH = 25
OUT_WIDTH = 29


@dataclass
class InRecord:
    loan_id: str
    principal: Decimal
    rate: Decimal
    term: Decimal

    @classmethod
    def parse(cls, line: str) -> "InRecord":
        line = line.ljust(25)
        return cls(
            loan_id=line[0:8].rstrip(),
            principal=parse_numeric(line[8:17], 9, 2, False, 'none'),
            rate=parse_numeric(line[17:22], 5, 4, False, 'none'),
            term=parse_numeric(line[22:25], 3, 0, False, 'none'),
        )

    def format(self) -> str:
        return (
            format_alpha(self.loan_id, 8)
            + format_numeric(self.principal, 9, 2, False, 'none')
            + format_numeric(self.rate, 5, 4, False, 'none')
            + format_numeric(self.term, 3, 0, False, 'none')
        ).rstrip()


@dataclass
class OutRecord:
    loan_id: str
    payment: Decimal
    interest: Decimal
    status: str

    @classmethod
    def parse(cls, line: str) -> "OutRecord":
        line = line.ljust(29)
        return cls(
            loan_id=line[0:8].rstrip(),
            payment=parse_numeric(line[8:17], 9, 2, False, 'none'),
            interest=parse_numeric(line[17:28], 10, 2, True, 'leading_sep'),
            status=line[28:29].rstrip(),
        )

    def format(self) -> str:
        return (
            format_alpha(self.loan_id, 8)
            + format_numeric(self.payment, 9, 2, False, 'none')
            + format_numeric(self.interest, 10, 2, True, 'leading_sep')
            + format_alpha(self.status, 1)
        ).rstrip()

